fn load_themes() -> HashMap<String, Theme> {
    let mut themes = HashMap::new();
    let themes_dir = Path::new("themes");
    if !themes_dir.exists() {
        return themes;
    }

    for entry in fs::read_dir(themes_dir).unwrap_or_else(|_| std::fs::read_dir(".").unwrap()) {
        let entry = entry.unwrap();
        let path = entry.path();
        if path.extension().map_or(false, |ext| ext == "yaml") || path.extension().map_or(false, |ext| ext == "yml") {
            let content = fs::read_to_string(&path).unwrap_or_default();
            if let Ok(theme) = serde_yaml::from_str::<Theme>(&content) {
                themes.insert(theme.name.clone(), theme);
            }
        }
    }
    themes
}

fn apply_theme(config: &mut Config, theme: &Theme) {
