    if let Some(bar) = &mut config.bar {
        bar.colors.separator = theme.colors.get("separator").cloned().unwrap_or_default();
        bar.colors.background = theme.colors.get("background").cloned().unwrap_or_default();
        bar.colors.statusline = theme.colors.get("statusline").cloned().unwrap_or_default();
        bar.colors.focused_workspace = theme.colors.get("focused_workspace")
            .and_then(|v| v.split(' ').filter(|s| !s.is_empty()).map(|s| s.to_string()).collect())
            .unwrap_or_else(|| vec!["#664477".to_string(), "#664477".to_string(), "#cccccc".to_string(), "#e7d8b1".to_string()]);
        bar.colors.active_workspace = theme.colors.get("active_workspace")
            .and_then(|v| v.split(' ').filter(|s| !s.is_empty()).map(|s| s.to_string()).collect())
            .unwrap_or_else(|| vec!["#DCCD69".to_string(), "#DCCD69".to_string(), "#181715".to_string(), "#A074C4".to_string()]);
        bar.colors.inactive_workspace = theme.colors.get("inactive_workspace")
            .and_then(|v| v.split(' ').filter(|s| !s.is_empty()).map(|s| s.to_string()).collect())
            .unwrap_or_else(|| vec!["#222133".to_string(), "#222133".to_string(), "#AAAAAA".to_string(), "#A074C4".to_string()]);
        bar.colors.urgent_workspace = theme.colors.get("urgent_workspace")
            .and_then(|v| v.split(' ').filter(|s| !s.is_empty()).map(|s| s.to_string()).collect())
            .unwrap_or_else(|| vec!["#CE4045".to_string(), "#CE4045".to_string(), "#FFFFFF".to_string(), "#DCCD69".to_string()]);
    }

    // Apply client colors
