fn convert_to_theme(config: &Config) -> String {
    let mut theme = Theme {
        name: "generated".to_string(),
        colors: HashMap::new(),
    };

    if let Some(bar) = &config.bar {
        theme.colors.insert("separator".to_string(), bar.colors.separator.clone());
        theme.colors.insert("background".to_string(), bar.colors.background.clone());
        theme.colors.insert("statusline".to_string(), bar.colors.statusline.clone());
        theme.colors.insert("focused_workspace".to_string(), bar.colors.focused_workspace.join(" "));
        theme.colors.insert("active_workspace".to_string(), bar.colors.active_workspace.join(" "));
        theme.colors.insert("inactive_workspace".to_string(), bar.colors.inactive_workspace.join(" "));
        theme.colors.insert("urgent_workspace".to_string(), bar.colors.urgent_workspace.join(" "));
    }

    theme.colors.insert("client.focused".to_string(), config.client_colors.focused.join(" "));
    theme.colors.insert("client.focused_inactive".to_string(), config.client_colors.focused_inactive.join(" "));
    theme.colors.insert("client.unfocused".to_string(), config.client_colors.unfocused.join(" "));
    theme.colors.insert("client.urgent".to_string(), config.client_colors.urgent.join(" "));

    serde_yaml::to_string(&theme).unwrap_or_default()
}
