fn main() {
    let args = Args::parse();

    if args.help {
        println!("{}", Args::into_app().render_help());
        std::process::exit(0);
    }

    if args.version {
        println!("i3-style 1.0");
        std::process::exit(0);
    }

    if args.list_all {
        let themes = load_themes();
        println!("\nAvailable themes:\n");
        for (name, theme) in themes.iter().sorted_by_key(|(_, t)| t.name.clone()) {
            println!("  {} - {}", name, theme.name);
        }
        std::process::exit(0);
    }

    let config_path = args.config.as_deref()
        .or_else(|| {
            std::env::var("XDG_CONFIG_HOME")
                .ok()
                .and_then(|h| Path::new(&h).join("i3").join("config").to_str().map(String::from))
        })
        .or_else(|| {
            std::env::var("HOME")
                .ok()
                .and_then(|h| Path::new(&h).join(".config").join("i3").join("config").to_str().map(String::from))
        })
        .unwrap_or_else(|| "~/.config/i3/config".to_string());

    let config_path = Path::new(&config_path);

    if args.to_theme.is_some() {
        let config_content = fs::read_to_string(&config_path).unwrap_or_default();
        if config_content.is_empty() {
            eprintln!("Could not read config file: {}", config_path.display());
            std::process::exit(1);
        }

        let config: Config = match serde_yaml::from_str(&config_content) {
            Ok(c) => c,
            Err(e) => {
                eprintln!("Failed to parse config: {}", e);
                std::process::exit(1);
            }
        };

        let theme_yaml = convert_to_theme(&config);
        if let Some(output) = &args.output {
            fs::write(output, &theme_yaml).unwrap_or_else(|e| {
                eprintln!("Failed to write theme to {}: {}", output, e);
                std::process::exit(1);
            });
        } else {
            print!("{}", theme_yaml);
        }
        std::process::exit(0);
    }

    let theme_name = args.theme.as_deref()
        .or_else(|| {
            std::env::var("I3_STYLE_THEME")
                .ok()
                .filter(|s| !s.is_empty())
        })
        .unwrap_or_else(|| "default".to_string());

    let theme = load_themes().get(&theme_name)
        .or_else(|| {
            let path = Path::new(&theme_name);
            if path.exists() {
                let content = fs::read_to_string(path).unwrap_or_default();
                if !content.is_empty() {
                    serde_yaml::from_str::<Theme>(&content).ok()
                } else {
                    None
                }
            } else {
                None
            }
        })
        .unwrap_or_else(|| {
            eprintln!("Unknown theme: {}", theme_name);
            std::process::exit(1);
        });

    let config_content = fs::read_to_string(&config_path).unwrap_or_else(|e| {
        eprintln!("Could not read config file: {}", e);
        std::process::exit(1);
    });

    let mut config: Config = match serde_yaml::from_str(&config_content) {
        Ok(c) => c,
        Err(e) => {
            eprintln!("Failed to parse config: {}", e);
            std::process::exit(1);
        }
    };

    apply_theme(&mut config, &theme);

    let output_path = if args.save {
        config_path.to_path_buf()
    } else if let Some(ref output) = args.output {
        Path::new(output).to_path_buf()
    } else {
        eprintln!("No output file specified. Use -o or -s to specify output.");
        std::process::exit(1);
    };

    let output_yaml = serde_yaml::to_string(&config).unwrap_or_else(|e| {
        eprintln!("Failed to serialize config: {}", e);
        std::process::exit(1);
    });

    if let Some(ref output) = args.output {
        fs::write(output, &output_yaml).unwrap_or_else(|e| {
            eprintln!("Failed to write output to {}: {}", output, e);
            std::process::exit(1);
        });
    } else {
        print!("{}", output_yaml);
    }

    if args.reload {
        let output_str = if let Some(ref output) = args.output {
            output
        } else {
            &config_path.to_string_lossy()
        };
        let _ = std::process::Command::new("i3-msg")
            .arg("reload")
            .output();
    }

    std::process::exit(0);
}
