fn main() {
    let args: Vec<String> = env::args().collect();

    if args.len() < 2 {
        eprintln!("Select a theme as the first argument. Use `--list-all` to see the themes.");
        std::process::exit(1);
    }

    let mut i = 1;
    let mut config_path: Option<String> = None;
    let mut output_path: Option<String> = None;
    let mut to_theme_path: Option<String> = None;
    let mut theme_name: Option<String> = None;
    let mut list_all = false;
    let mut reload = false;
    let mut save = false;
    let mut help_shown = false;

    while i < args.len() {
        let arg = &args[i];

        if arg == "--help" || arg == "-h" {
            print_help();
            help_shown = true;
            i += 1;
            continue;
        }

        if arg == "--version" || arg == "-V" {
            println!("i3-style 1.0");
            i += 1;
            continue;
        }

        if arg == "--list-all" || arg == "-l" {
            list_all = true;
            i += 1;
            continue;
        }

        if arg == "--reload" || arg == "-r" {
            reload = true;
            i += 1;
            continue;
        }

        if arg == "--save" || arg == "-s" {
            save = true;
            i += 1;
            continue;
        }

        if arg == "--config" || arg == "-c" {
            if i + 1 >= args.len() {
                eprintln!("Error: --config requires a path argument");
                std::process::exit(1);
            }
            config_path = Some(args[i + 1].clone());
            i += 2;
            continue;
        }

        if arg == "--output" || arg == "-o" {
            if i + 1 >= args.len() {
                eprintln!("Error: --output requires a path argument");
                std::process::exit(1);
            }
            output_path = Some(args[i + 1].clone());
            i += 2;
            continue;
        }

        if arg == "--to-theme" || arg == "-t" {
            if i + 1 >= args.len() {
                eprintln!("Error: --to-theme requires a path argument");
                std::process::exit(1);
            }
            to_theme_path = Some(args[i + 1].clone());
            i += 2;
            continue;
        }

        if arg.starts_with('-') {
            eprintln!("Unknown option: {}", arg);
            std::process::exit(1);
        }

        if theme_name.is_none() {
            theme_name = Some(arg.clone());
        } else {
            eprintln!("Error: Multiple themes specified");
            std::process::exit(1);
        }

        i += 1;
    }

    if help_shown {
        return;
    }

    if list_all {
        print_available_themes();
        return;
    }

    if let Some(path) = to_theme_path {
        if let Err(e) = convert_to_theme(&path) {
            eprintln!("Error: {}", e);
            std::process::exit(1);
        }
        return;
    }

    if let Some(name) = theme_name {
        if let Err(e) = apply_theme(&name, &config_path, &output_path, save, reload) {
            eprintln!("Error: {}", e);
            std::process::exit(1);
        }
    }
}
