fn apply_theme(theme_name: &str, config_path: &Option<String>, output_path: &Option<String>, save: bool, reload: bool) -> Result<(), String> {
    let theme = get_theme(theme_name)?;

    let config_content = if let Some(path) = config_path {
        fs::read_to_string(path)
            .map_err(|e| format!("Could not read config file: {}", e))?
    } else {
        let default_config = "/etc/i3/config";
        if Path::new(default_config).exists() {
            fs::read_to_string(default_config)
                .map_err(|e| format!("Could not read config file: {}", e))?
        } else {
            return Err(format!("Could not find config file at {}", default_config));
        }
    };

    let mut result = apply_theme_to_config(&config_content, &theme);

    if let Some(path) = output_path {
        if !save {
            result = validate_config(&result)?;
        }
        fs::write(path, &result)
            .map_err(|e| format!("Could not write output file: {}", e))?;
    } else if save {
        let final_path = config_path.as_ref().unwrap_or(&default_config_path());
        fs::write(final_path, &result)
            .map_err(|e| format!("Could not write config file: {}", e))?;
    }

    if reload {
        reload_config(config_path.as_deref())?;
    }

    Ok(())
}

fn default_config_path() -> &'static str {
    "/etc/i3/config"
}
