fn validate_config(config: &str) -> Result<String, String> {
    let output = which("i3")
        .map_err(|e| format!("Could not find i3 in PATH: {}", e))?;

    let result = std::process::Command::new(&output)
        .args(&["-C", "-c", "-"])
        .input(config.as_bytes())
        .output()
        .map_err(|e| format!("Could not run i3: {}", e))?;

    if !result.status.success() {
        let stderr = String::from_utf8_lossy(&result.stderr);
        return Err(format!("Could not validate config with `{}`: {}", output, stderr));
    }

    Ok(config.to_string())
}

fn reload_config(config_path: Option<&str>) -> Result<(), String> {
    let path = config_path.unwrap_or_else(default_config_path);
    let output = which("i3")
        .map_err(|e| format!("Could not find i3 in PATH: {}", e))?;

    let result = std::process::Command::new(&output)
        .args(&["-C", "-c", path])
        .output()
        .map_err(|e| format!("Could not run i3: {}", e))?;

    if !result.status.success() {
        let stderr = String::from_utf8_lossy(&result.stderr);
        return Err(format!("Could not reload config: {}", stderr));
    }

    Ok(())
}
