def parse_hex(s):
    """Parse a hex color string to RGB tuple."""
    s = s.lstrip('#')
    if len(s) != 6:
        return None
    try:
        r = int(s[0:2], 16)
        g = int(s[2:4], 16)
        b = int(s[4:6], 16)
        return (r, g, b)
