    def __init__(self, r, g, b):
        self.r = r
        self.g = g
        self.b = b

    def to_hex(self):
        return to_hex((self.r, self.g, self.b))


class Theme:
    def __init__(self, name):
        self.name = name
        self.colors = {}

    def add_color(self, key, colors):
        self.colors[key] = colors


