    """Load a theme from a YAML file."""
    with open(path, 'r') as f:
        content = f.read()

    # Simple YAML parsing for theme files
    lines = content.split('\n')
    name = None
    colors = {}

    in_colors = False
    current_key = None

    for line in lines:
        line = line.strip()
        if line.startswith('#') or not line:
            continue

        if line.startswith('name:'):
            name = line.split(':', 1)[1].strip()
        elif line.startswith('colors:'):
            in_colors = True
            current_key = None
        elif in_colors and line.startswith('  '):
            # Parse color entry like: separator:
            if ':' in line:
                key = line.split(':')[0].strip()
                current_key = key
                in_colors = False
            elif current_key and line.startswith('    '):
                # Parse color value like: - "#AAAAAA"
                val = line.strip().strip('"').strip("'")
                if val.startswith('#'):
