def parse_hex(s):
    """Parse a hex color string to RGB tuple."""
    s = s.lstrip('#')
    if len(s) != 6:
        return None
    try:
        r = int(s[0:2], 16)
        g = int(s[2:4], 16)
        b = int(s[4:6], 16)
        return (r, g, b)
    except ValueError:
        return None


def to_hex(rgb):
    """Convert RGB tuple to hex string."""
    return f"#{rgb[0]:02X}{rgb[1]:02X}{rgb[2]:02X}"


class Color:
    def __init__(self, r, g, b):
        self.r = r
        self.g = g
        self.b = b

    def to_hex(self):
        return to_hex((self.r, self.g, self.b))


class Theme:
    def __init__(self, name):
        self.name = name
        self.colors = {}

    def add_color(self, key, colors):
        self.colors[key] = colors


def get_default_config_path():
    home = os.environ.get('HOME', '.')
    return os.path.join(home, '.config', 'i3', 'config')


def load_theme_from_file(path):
    """Load a theme from a YAML file."""
    with open(path, 'r') as f:
        content = f.read()

    # Simple YAML parsing for theme files
    lines = content.split('\n')
    name = None
    colors = {}

    in_colors = False
    current_key = None

    for line in lines:
        line = line.strip()
        if line.startswith('#') or not line:
            continue

        if line.startswith('name:'):
            name = line.split(':', 1)[1].strip()
        elif line.startswith('colors:'):
            in_colors = True
            current_key = None
        elif in_colors and line.startswith('  '):
            # Parse color entry like: separator:
            if ':' in line:
                key = line.split(':')[0].strip()
                current_key = key
                in_colors = False
            elif current_key and line.startswith('    '):
                # Parse color value like: - "#AAAAAA"
                val = line.strip().strip('"').strip("'")
                if val.startswith('#'):
                    rgb = parse_hex(val)
                    if rgb:
                        colors.setdefault(current_key, []).append(Color(*rgb))

    if name is None:
        name = Path(path).stem

    theme = Theme(name)
    for key, color_list in colors.items():
        theme.add_color(key, color_list)

