+            result.push_str("    statusline #268bd2\n");
+            result.push_str("    focused_workspace #fdf6e3 #859900 #fdf6e3\n");
+            result.push_str("    active_workspace #fdf6e3 #6c71c4 #fdf6e3\n");
+            result.push_str("    inactive_workspace #586e75 #93a1a1 #002b36\n");
+            result.push_str("    urgent_workspace #d33682 #d33682 #fdf6e3\n");
+            result.push_str("  }\n");
+            result.push_str("}\n");
+            result.push_str("client.focused #859900 #859900 #fdf6e3 #6c71c4\n");
+            result.push_str("client.focused_inactive #073642 #073642 #eee8d5 #6c71c4\n");
+            result.push_str("client.unfocused #073642 #073642 #93a1a1 #586e75\n");
+            result.push_str("client.urgent #d33682 #d33682 #fdf6e3 #dc322f\n");
+            result
+        }
+        "purple" => {
+            let mut result = String::new();
+            result.push_str("# i3 config file (v4)\n");
+            result.push_str("#\n");
+            result.push_str("# Please see http://i3wm.org/docs/userguide.html for a complete reference!\n");
+            result.push_str("#\n");
+            result.push_str("# This config file uses keycodes (bindsym) and was written for the QWERTY\n");
+            result.push_str("# layout.\n");
+            result.push_str("#\n");
+            result.push_str("# To get a config file with the same key positions, but for your current\n");
+            result.push_str("# layout, use the i3-config-wizard\n");
+            result.push_str("#\n");
+            result.push_str("\n");
+            result.push_str("# Font for window titles. Will also be used by the bar unless a different font\n");
+            result.push_str("# is used in the bar {} block below. ISO 10646 = Unicode\n");
+            result.push_str("font -misc-fixed-medium-r-normal--13-120-75-75-C-70-iso10646-1\n");
